using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Configs;
using BenchmarkDotNet.Jobs;
using BenchmarkDotNet.Running;
using BenchmarkDotNet.Toolchains.CsProj;
using TextAnalysis;

var config = DefaultConfig.Instance
    .AddJob(Job.ShortRun.WithToolchain(CsProjCoreToolchain.NetCoreApp90).WithId("net9.0"))
    .AddJob(Job.ShortRun.WithToolchain(CsProjCoreToolchain.NetCoreApp10_0).WithId("net10.0"));

BenchmarkRunner.Run<TextAnalyzerBenchmarks>(config, args);

[MemoryDiagnoser(false)]
public class TextAnalyzerBenchmarks
{
    private TextAnalyzer _analyzer = null!;

    private const string SampleText =
        "The quick brown fox jumps over the lazy dog and the fox was very quick indeed " +
        "so the dog decided to also be quick but the fox was quicker than the dog ever was " +
        "because the fox had practiced jumping over lazy dogs for many years and the dog " +
        "simply could not keep up with the extraordinarily fast and agile brown fox who " +
        "loved nothing more than jumping over lazy dogs in the warm summer sunshine while " +
        "the birds sang beautiful songs in the tall green trees nearby the old stone wall";

    [GlobalSetup]
    public void Setup()
    {
        _analyzer = new TextAnalyzer(SampleText);
    }

    [Benchmark]
    public double AverageWordLength() => _analyzer.AverageWordLength();

    [Benchmark]
    public object WordLengthHistogram() => _analyzer.WordLengthHistogram();

    [Benchmark]
    public int UniqueWordCount() => _analyzer.UniqueWordCount();
}

